import itertools 

objects =['blue jay','quail','falcon']
options ={
'A':lambda p :p [1 ]=='blue jay',
'B':lambda p :p [1 ]=='quail',
'C':lambda p :p [1 ]=='falcon'
}

constraints =[
lambda p :p .index ('falcon')>p .index ('blue jay'),
lambda p :p .index ('blue jay')>p .index ('quail')
]

valid_permutations =[]
for p in itertools .permutations (objects ):
    if all (c (p )for c in constraints ):
        valid_permutations .append (p )

for opt ,func in options .items ():
    if any (func (p )for p in valid_permutations ):
        print (f'({opt })')
        break
